PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "departments" ("id" integer primary key autoincrement not null, "nome" varchar not null, "logo" varchar, "email" varchar, "telefone_principal" varchar, "telefone_secundario" varchar, "rua" varchar, "numero" varchar, "bairro" varchar, "cidade" varchar, "cep" varchar, "uf" varchar, "complemento" varchar, "created_at" datetime, "updated_at" datetime, "cnpj" varchar, "send_message" tinyint(1) not null default '0', "webhook_n8n_service" varchar, "webhook_n8n_order" varchar, "webhook_n8n_campaign" varchar);
CREATE TABLE IF NOT EXISTS "positions" ("id" integer primary key autoincrement not null, "nome" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "nivel" varchar not null default 'padrao', "whatsapp" varchar, "is_ativo" tinyint(1) not null default '0', "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "position_id" integer, "departamento_id" integer, "two_factor_secret" text, "two_factor_recovery_codes" text, foreign key("position_id") references "positions"("id"), foreign key("departamento_id") references "departments"("id"));
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "titulo" varchar not null, "departamento_id" integer not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "subcategories" ("id" integer primary key autoincrement not null, "titulo" varchar not null, "categoria_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("categoria_id") references "categories"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "people" ("id" integer primary key autoincrement not null, "nome" varchar not null, "apelido" varchar, "cpf" varchar not null, "whatsapp" varchar, "genero" varchar, "escolaridade" varchar, "data_nascimento" date, "rua" varchar, "numero" varchar, "bairro" varchar, "cidade" varchar, "cep" varchar, "uf" varchar, "latitude" numeric, "longitude" numeric, "geocoded_at" datetime, "complemento" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "groups" ("id" integer primary key autoincrement not null, "nome" varchar not null, "descricao" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "group_people" ("id" integer primary key autoincrement not null, "group_id" integer not null, "people_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("group_id") references "groups"("id") on delete cascade, foreign key("people_id") references "people"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "campaigns" ("id" integer primary key autoincrement not null, "name" varchar not null, "message" text not null, "image_url" varchar, "video_url" varchar, "audio_url" varchar, "recipients" text not null, "status" varchar check ("status" in ('pending', 'in_progress', 'completed', 'failed')) not null default 'pending', "created_at" datetime, "updated_at" datetime, "scheduled_at" datetime, "is_scheduled" tinyint(1) not null default '0', "sent_count" integer not null default '0', "fail_count" integer not null default '0', "sent_at" datetime);
CREATE TABLE IF NOT EXISTS "campaign_group" ("id" integer primary key autoincrement not null, "campaign_id" integer not null, "group_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("campaign_id") references "campaigns"("id") on delete cascade, foreign key("group_id") references "groups"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "configurations" ("id" integer primary key autoincrement not null, "nome_fantasia" varchar, "razao_social" varchar, "cnpj" varchar, "telefone_principal" varchar, "whatsapp" varchar, "email" varchar, "logo" varchar, "avatar" varchar, "rua" varchar, "numero" varchar, "bairro" varchar, "cidade" varchar, "cep" varchar, "estado" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "orders" ("id" integer primary key autoincrement not null, "descricao" text, "status" varchar default 'Em Aberto', "solucao" text, "previsao_solucao" date, "data_transferencia" date, "created_at" datetime, "updated_at" datetime, "categoria_id" integer, "subcategoria_id" integer, "create_user_id" integer, "responsavel_user_id" integer, "pessoa_id" integer, "update_user_id" integer, "dono_setor_id" integer, "antigo_setor_id" integer, "rua" varchar, "numero" varchar, "bairro" varchar, "cidade" varchar, "cep" varchar, "uf" varchar, "complemento" varchar, foreign key("categoria_id") references "categories"("id") on delete cascade, foreign key("subcategoria_id") references "subcategories"("id") on delete cascade, foreign key("create_user_id") references "users"("id") on delete cascade, foreign key("responsavel_user_id") references "users"("id") on delete cascade, foreign key("pessoa_id") references "people"("id") on delete cascade, foreign key("update_user_id") references "users"("id") on delete cascade, foreign key("dono_setor_id") references "departments"("id") on delete cascade, foreign key("antigo_setor_id") references "departments"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "historics" ("id" integer primary key autoincrement not null, "descricao" text not null, "created_at" datetime, "updated_at" datetime, "user_id" integer, "order_id" integer, foreign key("user_id") references "users"("id") on delete cascade, foreign key("order_id") references "orders"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "services" ("id" integer primary key autoincrement not null, "observacao" varchar, "pessoa_id" integer not null, "categoria_id" integer not null, "user_id" integer, "data" datetime, "notas" text, "confirmacao" tinyint(1), "created_at" datetime, "updated_at" datetime, "status" varchar default ('Em Aberto'), "departamento_id" integer, foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("categoria_id") references categories("id") on delete cascade on update no action, foreign key("pessoa_id") references people("id") on delete cascade on update no action, foreign key("departamento_id") references "departments"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "nps" ("id" integer primary key autoincrement not null, "titulo" varchar not null, "texto" text, "departamento_id" integer, "order_id" integer, "service_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("departamento_id") references "departments"("id") on delete cascade, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("service_id") references "services"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "nps_responses" ("id" integer primary key autoincrement not null, "nps_id" integer not null, "rating" integer not null, "whatsapp" varchar, "expired_at" datetime not null default '2025-05-21 11:12:20', "created_at" datetime, "updated_at" datetime, foreign key("nps_id") references "nps"("id") on delete cascade);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "people_cpf_unique" on "people" ("cpf");
CREATE INDEX people_nome_index ON people(nome);
CREATE INDEX people_cpf_index ON people(cpf);
CREATE INDEX positions_nome_index ON positions(nome);
COMMIT;
